--
-- Table structure for table `energy_storage`
--

DROP TABLE IF EXISTS `energy_storage`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `energy_storage` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `storage_name` varchar(100) NOT NULL COMMENT '储能系统名称',
  `storage_code` varchar(50) NOT NULL COMMENT '储能系统编号',
  `storage_type` varchar(10) DEFAULT '1' COMMENT '储能类型（1-锂电池 2-铅酸电池 3-液流电池 4-超级电容）',
  `capacity` decimal(10,2) DEFAULT '0.00' COMMENT '额定容量(kWh)',
  `power` decimal(10,2) DEFAULT '0.00' COMMENT '额定功率(kW)',
  `voltage_level` varchar(20) DEFAULT NULL COMMENT '电压等级',
  `area_id` bigint DEFAULT NULL COMMENT '所属区域ID',
  `longitude` decimal(10,6) DEFAULT NULL COMMENT '经度',
  `latitude` decimal(10,6) DEFAULT NULL COMMENT '纬度',
  `install_date` date DEFAULT NULL COMMENT '安装日期',
  `grid_date` date DEFAULT NULL COMMENT '并网日期',
  `design_life` int DEFAULT '10' COMMENT '设计寿命(年)',
  `manufacturer` varchar(100) DEFAULT NULL COMMENT '制造商',
  `model` varchar(100) DEFAULT NULL COMMENT '设备型号',
  `status` varchar(1) DEFAULT '1' COMMENT '系统状态（0-停用 1-正常 2-故障 3-维护 4-充电中 5-放电中）',
  `manager` varchar(50) DEFAULT NULL COMMENT '负责人',
  `contact_phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_storage_code` (`storage_code`),
  KEY `idx_area_id` (`area_id`),
  KEY `idx_status` (`status`),
  KEY `idx_del_flag` (`del_flag`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='储能系统信息表';
