--
-- Table structure for table `sys_integration_config`
--

DROP TABLE IF EXISTS `sys_integration_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_integration_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '配置ID',
  `system_code` varchar(50) NOT NULL COMMENT '系统编码（MES、ERP、环保、消防）',
  `system_name` varchar(255) NOT NULL COMMENT '系统名称',
  `connection_url` varchar(500) DEFAULT NULL COMMENT '连接URL',
  `username` varchar(100) DEFAULT NULL COMMENT '用户名',
  `password` varchar(255) DEFAULT NULL COMMENT '密码（加密存储）',
  `api_key` varchar(255) DEFAULT NULL COMMENT 'API密钥',
  `timeout` int DEFAULT '30000' COMMENT '连接超时时间（毫秒）',
  `description` varchar(500) DEFAULT NULL COMMENT '描述',
  `status` tinyint DEFAULT '1' COMMENT '状态（1-启用，2-禁用）',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_system_code` (`system_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统集成配置表';
