--
-- Table structure for table `sys_interface_config`
--

DROP TABLE IF EXISTS `sys_interface_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_interface_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '接口ID',
  `config_id` bigint NOT NULL COMMENT '所属系统配置ID',
  `interface_code` varchar(50) NOT NULL COMMENT '接口编码',
  `interface_name` varchar(255) NOT NULL COMMENT '接口名称',
  `url` varchar(500) NOT NULL COMMENT '接口URL',
  `method` varchar(10) NOT NULL DEFAULT 'GET' COMMENT '请求方法（GET、POST、PUT、DELETE）',
  `request_headers` text COMMENT '请求头（JSON格式）',
  `request_params` text COMMENT '请求参数（JSON格式）',
  `request_body` text COMMENT '请求体（JSON格式）',
  `response_params` text COMMENT '响应参数（JSON格式）',
  `auth_type` varchar(20) DEFAULT 'NONE' COMMENT '认证类型（NONE、BASIC、BEARER、API_KEY）',
  `retry_count` int DEFAULT '3' COMMENT '重试次数',
  `retry_interval` int DEFAULT '1000' COMMENT '重试间隔（毫秒）',
  `status` tinyint DEFAULT '1' COMMENT '状态（1-启用，2-禁用）',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_interface_code` (`interface_code`),
  KEY `idx_config_id` (`config_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='接口配置表';
/*!40101 SET character_set_client = @saved_cs_client */;

