-- Table structure for table `sys_monitor_alert`
--

DROP TABLE IF EXISTS `sys_monitor_alert`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_monitor_alert` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '告警ID',
  `alert_type` varchar(50) NOT NULL COMMENT '告警类型',
  `alert_level` varchar(20) NOT NULL COMMENT '告警级别（INFO、WARN、ERROR、CRITICAL）',
  `alert_title` varchar(255) NOT NULL COMMENT '告警标题',
  `alert_content` text NOT NULL COMMENT '告警内容',
  `related_system` varchar(50) DEFAULT NULL COMMENT '关联系统',
  `related_task_id` bigint DEFAULT NULL COMMENT '关联任务ID',
  `status` int DEFAULT '1' COMMENT '告警状态（1-未处理，2-已处理）',
  `handler` varchar(100) DEFAULT NULL COMMENT '处理人',
  `handle_time` datetime DEFAULT NULL COMMENT '处理时间',
  `handle_result` text COMMENT '处理结果',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_alert_level` (`alert_level`),
  KEY `idx_status` (`status`),
  KEY `idx_related_system` (`related_system`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='监控告警表';
