DROP TABLE IF EXISTS `weather_forecast`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `weather_forecast` (
  `weather_id` bigint NOT NULL AUTO_INCREMENT COMMENT '天气预测ID',
  `predicted_time` datetime DEFAULT NULL COMMENT '预测时间',
  `temperature` decimal(5,2) DEFAULT NULL COMMENT '温度（℃）',
  `humidity` decimal(5,2) DEFAULT NULL COMMENT '湿度（%）',
  `wind_speed` decimal(5,2) DEFAULT NULL COMMENT '风速（m/s）',
  `solar_radiation` decimal(5,2) DEFAULT NULL COMMENT '太阳辐射（W/m²）',
  `weather_condition` varchar(50) DEFAULT NULL COMMENT '天气状况',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`weather_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='天气预测表';
/*!40101 SET character_set_client = @saved_cs_client */;

